INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (15, 2, 'theory', 'The OSI and TCP/IP Models: Layers and Encapsulation');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 2, 0, 'What happens to data as it is sent down the stack?', '["Each layer removes the header of the previous one", "The data is encrypted at every layer", "Each layer adds its own header: the data is wrapped in envelopes", "The data is copied into several streams"]', 2, 'This is encapsulation: segment → packet → frame, with its own header at each layer.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 2, 1, 'Up to which layer does an ordinary switch unwrap a frame?', '["To the link layer", "To the application layer", "To the transport layer", "To the network layer"]', 0, 'A switch looks at the MAC address in the link header and does not read the packet inside.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 2, 2, 'What stays unchanged when a packet passes through a router?', '["The sender and receiver MAC addresses", "The frame checksum", "The frame type and size", "The sender and receiver IP addresses"]', 3, 'IP addresses are end to end; the frame is rebuilt on every hop with new MAC addresses (the TTL changes too).');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 2, 3, 'Which layer of the TCP/IP stack chooses the receiving program by port number?', '["Link", "Transport", "Network", "Physical"]', 1, 'The port is a field of the TCP or UDP header, that is, of the transport layer.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 2, 4, 'You see that ping fails, but the cable is plugged in and the light is on. Where do you continue under the bottom-up rule?', '["Check the application code", "Reinstall the browser", "Check the service port and the firewall", "Check the switch port and MAC addresses, then the address, mask, and route"]', 3, 'After the physical layer comes the link layer, then the network layer; transport and the application are checked last.');
